@RestController
public class ProductController {

    private static final Pattern SKU = Pattern.compile("[A-Z]{3}-\\d{4}");

    @Autowired
    private ProductRepository productRepository;
    @Autowired
    private PriceHistoryRepository priceHistoryRepository;

    @Value("${customer.service.url}")
    private String customerServiceUrl;

    private final RestTemplate restTemplate = newRestTemplate();

    // C1
    @GetMapping("/products")
    public List<Product> list(@RequestParam(name = "category", required = false) String category,
            @RequestParam(name = "minPrice", required = false) BigDecimal minPrice,
            @RequestParam(name = "maxPrice", required = false) BigDecimal maxPrice,
            @RequestParam(name = "available", required = false) Boolean available) {
        Category wanted = category == null ? null : Category.valueOf(category.toUpperCase());
        return productRepository.findAll().stream()
                .filter(p -> wanted == null || p.getCategory() == wanted)
                .filter(p -> {
                    BigDecimal effective = p.getSalePrice() != null ? p.getSalePrice() : p.getBasePrice();
                    return (minPrice == null || effective.compareTo(minPrice) >= 0)
                            && (maxPrice == null || effective.compareTo(maxPrice) <= 0);
                })
                .filter(p -> available == null || p.isAvailable() == available)
                .sorted((a, b) -> a.getSku().compareTo(b.getSku()))
                .collect(Collectors.toList());
    }

    // C2
    @GetMapping("/products/{sku}")
    public Product get(@PathVariable("sku") String sku,
            @RequestParam(name = "customerId", required = false) Long customerId) {
        Product p = productRepository.findById(sku).orElseThrow(() -> new ProductNotFoundException(sku));
        String tier = "STANDARD";
        if (customerId != null) {
            tier = fetchTier(customerId);
        }
        if (p.getSalePrice() != null) {
            p.setCustomerPrice(PriceUtils.round2(p.getSalePrice()));
        } else {
            p.setCustomerPrice(PriceUtils.applyTier(p.getBasePrice(), tier));
        }
        return p;
    }

    // C3
    @PostMapping("/products")
    public ResponseEntity<Object> create(@RequestBody Product body) {
        if (body.getSku() == null || !SKU.matcher(body.getSku()).matches()) {
            return error(HttpStatus.BAD_REQUEST, "sku must match [A-Z]{3}-\\d{4}");
        }
        if (body.getName() == null || body.getName().isBlank()) {
            return error(HttpStatus.BAD_REQUEST, "name is required");
        }
        if (body.getCategory() == null) {
            return error(HttpStatus.BAD_REQUEST, "category is required");
        }
        if (body.getBasePrice() == null || body.getBasePrice().signum() <= 0) {
            return error(HttpStatus.BAD_REQUEST, "basePrice must be > 0");
        }
        if (body.getWeightKg() == null || body.getWeightKg().signum() <= 0) {
            return error(HttpStatus.BAD_REQUEST, "weightKg must be > 0");
        }
        if (body.getStockQuantity() < 0) {
            return error(HttpStatus.BAD_REQUEST, "stockQuantity must be >= 0");
        }
        if (body.getSalePrice() != null
                && (body.getSalePrice().signum() <= 0 || body.getSalePrice().compareTo(body.getBasePrice()) >= 0)) {
            return error(HttpStatus.BAD_REQUEST, "salePrice must be > 0 and lower than basePrice");
        }
        if (productRepository.existsById(body.getSku())) {
            return error(HttpStatus.CONFLICT, "sku already exists");
        }
        body.setReservedQuantity(0);
        body.setCreatedAt(LocalDateTime.now());
        body.setBasePrice(PriceUtils.round2(body.getBasePrice()));
        if (body.getSalePrice() != null) {
            body.setSalePrice(PriceUtils.round2(body.getSalePrice()));
        }
        return ResponseEntity.status(HttpStatus.CREATED).body(productRepository.save(body));
    }

    // C4: a "salePrice": null in the body removes the sale
    @PutMapping("/products/{sku}/price")
    public ResponseEntity<Object> changePrice(@PathVariable("sku") String sku, @RequestBody Map<String, Object> body) {
        Product p = productRepository.findById(sku).orElseThrow(() -> new ProductNotFoundException(sku));
        boolean hasBase = body.containsKey("basePrice");
        boolean hasSale = body.containsKey("salePrice");
        if (!hasBase && !hasSale) {
            return error(HttpStatus.BAD_REQUEST, "basePrice and/or salePrice is required");
        }
        BigDecimal newBase = p.getBasePrice();
        BigDecimal newSale = p.getSalePrice();
        try {
            if (hasBase) {
                newBase = PriceUtils.round2(new BigDecimal(String.valueOf(body.get("basePrice"))));
            }
            if (hasSale) {
                newSale = body.get("salePrice") == null ? null
                        : PriceUtils.round2(new BigDecimal(String.valueOf(body.get("salePrice"))));
            }
        } catch (NumberFormatException e) {
            return error(HttpStatus.BAD_REQUEST, "prices must be numbers");
        }
        if (newBase.signum() <= 0) {
            return error(HttpStatus.BAD_REQUEST, "basePrice must be > 0");
        }
        if (newSale != null && (newSale.signum() <= 0 || newSale.compareTo(newBase) >= 0)) {
            return error(HttpStatus.BAD_REQUEST, "salePrice must be > 0 and lower than basePrice");
        }

        PriceHistory h = new PriceHistory();
        h.setSku(sku);
        h.setOldBasePrice(p.getBasePrice());
        h.setOldSalePrice(p.getSalePrice());
        h.setNewBasePrice(newBase);
        h.setNewSalePrice(newSale);
        h.setChangedAt(LocalDateTime.now());

        p.setBasePrice(newBase);
        p.setSalePrice(newSale);
        Product saved;
        try {
            saved = productRepository.saveAndFlush(p);
        } catch (RuntimeException e) {
            Throwable t = e;
            while (t != null) {
                if (t instanceof PriceRuleException) {
                    return error(HttpStatus.BAD_REQUEST, t.getMessage());
                }
                t = t.getCause();
            }
            throw e;
        }
        priceHistoryRepository.save(h);
        return ResponseEntity.ok(saved);
    }

    @SuppressWarnings("unchecked")
    private String fetchTier(long customerId) {
        Map<String, Object> customer = restTemplate.getForObject(customerServiceUrl + "/customers/{id}", Map.class, customerId);
        if (customer == null || !"OK".equals(customer.get("status"))) {
            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "customer not found: " + customerId);
        }
        return String.valueOf(customer.get("tier"));
    }

    private static RestTemplate newRestTemplate() {
        SimpleClientHttpRequestFactory factory = new SimpleClientHttpRequestFactory();
        factory.setConnectTimeout(2000);
        factory.setReadTimeout(5000);
        return new RestTemplate(factory);
    }

    private static ResponseEntity<Object> error(HttpStatus status, String message) {
        Map<String, Object> m = new LinkedHashMap<>();
        m.put("message", message);
        return ResponseEntity.status(status).body(m);
    }
}
